policy://examples/age_verification:
// =============================================================
// CSL-Core Example: Age Verification
// Goal: Protect minors from restricted content categories.
// =============================================================

CONFIG {
  ENFORCEMENT_MODE: BLOCK
}

DOMAIN AgeGate {

  VARIABLES {
    // User age
    user_age: 0..120

    // Content category requested
    category: {"GENERAL", "TEEN", "MATURE", "ALCOHOL"}

    // Is parent verified?
    parent_verified: {"YES", "NO"}
  }

  // -----------------------------------------------------------
  // Rule 1: Minors ( < 18) cannot access MATURE content
  // -----------------------------------------------------------
  STATE_CONSTRAINT no_mature_for_minors {
    WHEN user_age < 18
    THEN category MUST NOT BE "MATURE"
  }

  // -----------------------------------------------------------
  // Rule 2: Minors ( < 18) cannot access ALCOHOL content
  // -----------------------------------------------------------
  STATE_CONSTRAINT no_alcohol_for_minors {
    WHEN user_age < 18
    THEN category MUST NOT BE "ALCOHOL"
  }

  // -----------------------------------------------------------
  // Rule 3: Adults require ID verification for ALCOHOL
  // Fix: Added "AND user_age >= 18" to avoid conflict with Rule 2
  // -----------------------------------------------------------
  STATE_CONSTRAINT alcohol_requires_verification {
    WHEN category == "ALCOHOL" AND user_age >= 18
    THEN parent_verified MUST BE "YES"
  }
}

policy://examples/agent_tool_guard:
// =============================================================
// CSL-Core Example: Agent Tool Guard (v0.1)
// Goal: Deterministic permission + parameter safety for AI agents
// =============================================================

CONFIG {
  ENFORCEMENT_MODE: BLOCK
  CHECK_LOGICAL_CONSISTENCY: TRUE
  ENABLE_FORMAL_VERIFICATION: FALSE
  ENABLE_CAUSAL_INFERENCE: FALSE
  INTEGRATION: "native"
}

DOMAIN AgentToolGuard {

  VARIABLES {
    // Who is requesting / operating the agent
    user_role: {"ADMIN", "USER", "ANALYST"}

    // Which tool the agent is about to call
    tool: {"SEND_EMAIL", "TRANSFER_FUNDS", "QUERY_DB", "DELETE_RECORD"}

    // Optional, tool-dependent parameters
    amount: 0..100000
    recipient_domain: {"INTERNAL", "EXTERNAL"}
    db_table: {"CUSTOMERS", "TRANSACTIONS", "SECRETS"}
    pii_present: {"YES", "NO"}
    approval_token: {"YES", "NO"}
  }

  // -----------------------------------------------------------
  // 1) Non-admin users must never perform money transfers
  // -----------------------------------------------------------
  STATE_CONSTRAINT non_admin_no_transfer {
    WHEN user_role == "USER" OR user_role == "ANALYST"
    THEN tool MUST NOT BE "TRANSFER_FUNDS"
  }

  // -----------------------------------------------------------
  // 2) Money transfers require an explicit approval token
  //    (Simulates "human-in-the-loop" gate or signed approval)
  // -----------------------------------------------------------
  STATE_CONSTRAINT transfer_requires_approval {
    // Only applies to ADMIN transfers.
    // Non-admin transfers are already forbidden by non_admin_no_transfer.
    WHEN tool == "TRANSFER_FUNDS" AND user_role == "ADMIN"
    THEN approval_token == "YES"
  }


  // -----------------------------------------------------------
  // 3) Even admins have a hard transfer limit per action
  // -----------------------------------------------------------
  STATE_CONSTRAINT admin_transfer_limit {
    WHEN tool == "TRANSFER_FUNDS" AND user_role == "ADMIN"
    THEN amount <= 5000
  }

  // -----------------------------------------------------------
  // 4) If PII is present, agent may only email INTERNAL recipients
  // -----------------------------------------------------------
  STATE_CONSTRAINT no_external_email_with_pii {
    WHEN tool == "SEND_EMAIL" AND pii_present == "YES"
    THEN recipient_domain MUST NOT BE "EXTERNAL"
  }

  // -----------------------------------------------------------
  // 5) Restrict high-risk DB access: SECRETS table is forbidden
  // -----------------------------------------------------------
  STATE_CONSTRAINT no_secrets_table_queries {
    WHEN tool == "QUERY_DB"
    THEN db_table MUST NOT BE "SECRETS"
  }

  // -----------------------------------------------------------
  // 6) Dangerous destructive tool calls must never happen
  //    (Hard-ban DELETE_RECORD for this alpha example)
  // -----------------------------------------------------------
  STATE_CONSTRAINT no_delete_record_tool {
    ALWAYS True
    THEN tool MUST NOT BE "DELETE_RECORD"
  }
}

policy://examples/banking_guard:
// =============================================================
// CSL-Core Case Study: Banking Transfer Guard (v0.1)
// Goal: "Deterministic safety for probabilistic systems."
// =============================================================

CONFIG {
  ENFORCEMENT_MODE: BLOCK
  CHECK_LOGICAL_CONSISTENCY: TRUE
  ENABLE_FORMAL_VERIFICATION: FALSE
  ENABLE_CAUSAL_INFERENCE: FALSE
  INTEGRATION: "native"
}

DOMAIN BankingGuard {

  VARIABLES {
    action: {"TRANSFER", "WITHDRAW", "DEPOSIT"}
    amount: 0..100000
    country: {"TR", "US", "EU", "NK"}
    is_vip: {"TRUE", "FALSE"}
    kyc_level: 0..5
    risk_score: 0..1
    device_trust: 0..1
  }

  // -----------------------------------------------------------
  // 1) Hard sanctions: NK must never appear (fail-closed & clear)
  // -----------------------------------------------------------
  STATE_CONSTRAINT no_sanctioned_country {
  WHEN country == country
  THEN country MUST NOT BE "NK"
}

  // -----------------------------------------------------------
  // 2) Non-VIP transfer hard limit
  // -----------------------------------------------------------
  STATE_CONSTRAINT transfer_limit_non_vip {
    WHEN action == "TRANSFER" AND is_vip == "FALSE"
    THEN amount <= 1000
  }

  // -----------------------------------------------------------
  // 3) VIP transfer soft(er) limit
  // -----------------------------------------------------------
  STATE_CONSTRAINT transfer_limit_vip {
    WHEN action == "TRANSFER" AND is_vip == "TRUE"
    THEN amount <= 10000
  }

  // -----------------------------------------------------------
  // 4) Risk ceiling for transfers (blocks high-risk outputs)
  // -----------------------------------------------------------
  STATE_CONSTRAINT risk_ceiling_for_transfer {
    WHEN action == "TRANSFER"
    THEN risk_score <= 0.8
  }

  // -----------------------------------------------------------
  // 5) Device trust requirement for medium+ transfers
  // -----------------------------------------------------------
  STATE_CONSTRAINT device_trust_for_medium_transfer {
    WHEN action == "TRANSFER" AND amount > 300
    THEN device_trust >= 0.7
  }

  // -----------------------------------------------------------
  // 6) KYC for larger withdrawals
  // -----------------------------------------------------------
  STATE_CONSTRAINT kyc_for_large_withdraw {
    WHEN action == "WITHDRAW" AND amount > 500
    THEN kyc_level >= 2
  }
}

policy://examples/dao_treasury_guard:
// =============================================================
// CSL-Core Example: DAO Treasury Guard (v0.1)
// Goal: Deterministic permission + parameter safety for AI agents
// =============================================================

CONFIG {
    ENFORCEMENT_MODE: BLOCK
    CHECK_LOGICAL_CONSISTENCY: TRUE
    ENABLE_FORMAL_VERIFICATION: FALSE
    ENABLE_CAUSAL_INFERENCE: FALSE
    INTEGRATION: "native"
}

DOMAIN DAOTreasury {
    VARIABLES {
        transfer_amount: 0..10000000,
        total_balance: 0..100000000,
        proposal_id: 0..100000,
        approval_count: 0..100,
        proposer_reputation: 0..1000,
        proposal_age_hours: 0..720,
        destination_type: {"INTERNAL", "EXTERNAL", "BRIDGE", "MULTISIG"},
        action: {"TRANSFER", "GRANT", "INVESTMENT", "EMERGENCY"}
    }

    STATE_CONSTRAINT low_reputation_destination {
        WHEN proposer_reputation < 100
        THEN destination_type == "INTERNAL"
    }

    STATE_CONSTRAINT low_reputation_amount_limit {
        WHEN proposer_reputation < 100
        THEN transfer_amount <= 10000
    }

    STATE_CONSTRAINT external_transfer_approval {
        WHEN proposer_reputation >= 100 
             AND destination_type == "EXTERNAL" 
             AND transfer_amount > 50000
        THEN approval_count >= 5
    }

    STATE_CONSTRAINT bridge_transfer_max_approval {
        WHEN proposer_reputation >= 100 
             AND destination_type == "BRIDGE" 
             AND transfer_amount > 10000
        THEN approval_count >= 7
    }

    STATE_CONSTRAINT bridge_always_requires_timelock {
        WHEN proposer_reputation >= 100 
             AND destination_type == "BRIDGE" 
             AND action != "EMERGENCY"
        THEN proposal_age_hours >= 24
    }

    STATE_CONSTRAINT catastrophic_transfer_protection {
        WHEN transfer_amount > (total_balance * 0.1) AND action != "EMERGENCY"
        THEN approval_count >= 3
    }

    STATE_CONSTRAINT large_transfer_timelock {
        WHEN transfer_amount > (total_balance * 0.05) AND action != "EMERGENCY"
        THEN proposal_age_hours >= 24
    }

    STATE_CONSTRAINT emergency_action_unanimous {
        WHEN action == "EMERGENCY"
        THEN approval_count >= 10
    }

    STATE_CONSTRAINT valid_proposal {
        WHEN transfer_amount > 0
        THEN proposal_id > 0
    }
}

